messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Low-Poly Humanoid Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // Scene Setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    scene.add(dirLight);

    // Ground (Treadmill)
    const groundGeo = new THREE.PlaneGeometry(10, 20);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill texture effect (lines)
    const grid = new THREE.GridHelper(20, 20, 0x444444, 0x444444);
    grid.rotation.x = 0;
    grid.position.y = 0.01;
    scene.add(grid);

    // Humanoid Construction
    const bodyGroup = new THREE.Group();
    scene.add(bodyGroup);

    const mat = new THREE.MeshStandardMaterial({ color: 0x00ffcc });
    const darkMat = new THREE.MeshStandardMaterial({ color: 0x008877 });

    // Torso
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.8, 0.3), mat);
    torso.position.y = 1.5;
    torso.castShadow = true;
    bodyGroup.add(torso);

    // Head
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.3, 0.3), mat);
    head.position.y = 0.6;
    torso.add(head);

    // Limbs helper function
    function createLimb(w, h, d, color) {
        const group = new THREE.Group();
        const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), color);
        mesh.position.y = -h / 2; // Pivot from top
        mesh.castShadow = true;
        group.add(mesh);
        return group;
    }

    const leftArm = createLimb(0.15, 0.6, 0.15, mat);
    leftArm.position.set(0.4, 0.7, 0);
    torso.add(leftArm);

    const rightArm = createLimb(0.15, 0.6, 0.15, mat);
    rightArm.position.set(-0.4, 0.7, 0);
    torso.add(rightArm);

    const leftLeg = createLimb(0.2, 0.7, 0.2, darkMat);
    leftLeg.position.set(0.2, -0.4, 0);
    torso.add(leftLeg);

    const rightLeg = createLimb(0.2, 0.7, 0.2, darkMat);
    rightLeg.position.set(-0.2, -0.4, 0);
    torso.add(rightLeg);

    // Camera Position
    camera.position.set(4, 2.5, 4);
    camera.lookAt(0, 1.5, 0);

    // Animation Logic
    const clock = new THREE.Clock();

    function animate() {
        requestAnimationFrame(animate);
        const elapsed = clock.getElapsedTime() % 10; // 10s cycle

        // State Machine
        // 0-2s: Stand Still
        // 2-5s: Walk
        // 5-8s: Run
        // 8-10s: Stand Still

        let mode = 'idle';
        let speed = 0;
        let intensity = 0;
        let lean = 0;
        let treadmillSpeed = 0;

        if (elapsed < 2 || elapsed > 8) {
            mode = 'idle';
            speed = 0;
            intensity = 0;
            lean = 0;
            treadmillSpeed = 0;
        } else if (elapsed < 5) {
            mode = 'walk';
            speed = 1.5;
            intensity = 1.0;
            lean = 0;
            treadmillSpeed = 0.1;
        } else {
            mode = 'run';
            speed = 4.5;
            intensity = 2.2;
            lean = 0.25; // Forward lean
            treadmillSpeed = 0.3;
        }

        // Apply movement to body
        torso.rotation.x = lean;

        // Calculate limb oscillation
        // Use sin/cos for rhythmic movement
        const time = elapsed * speed;

        // Legs: opposite phases
        leftLeg.rotation.x = Math.sin(time) * (0.5 * intensity);
        rightLeg.rotation.x = Math.sin(time + Math.PI) * (0.5 * intensity);

        // Arms: opposite phase to legs
        leftArm.rotation.x = Math.sin(time + Math.PI) * (0.4 * intensity);
        rightArm.rotation.x = Math.sin(time) * (0.4 * intensity);

        // Vertical bobbing
        torso.position.y = 1.5 + (Math.sin(time * 2) * (0.05 * intensity));

        // Treadmill visual movement
        grid.position.z = (elapsed * 5) % 1; 

        renderer.render(scene, camera);
    }

    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>
</body>
</html>
```
